-- ── 6. ATUALIZAR STATUS DOS ASSISTENTES ──
-- Vincular assistentes às exposições pelo nome

DO $$
DECLARE
  exp RECORD;
  uid uuid;
  nomes text[];
  nome text;
BEGIN
  FOR exp IN SELECT id, assistente_nome FROM (
    SELECT e.id, e.titulo,
      CASE
        WHEN e.titulo IN (SELECT titulo FROM exposicoes) THEN NULL
        ELSE NULL
      END as assistente_nome
    FROM exposicoes e
  ) t LOOP
    -- noop placeholder for future assistant linking
    NULL;
  END LOOP;
END $$;


